package com.dvnnfrr.saku.excel

import java.io.File

/**
 * Locates the real Money Manager export that ships in the repository.
 *
 * Every Excel test reads this file rather than a synthetic workbook generated by the same
 * library under test. A file we wrote ourselves would exercise our own assumptions; this one
 * carries the quirks that actually broke things — a duplicated `Account` header, a `dimension`
 * element that understates the sheet, amounts stored as text alongside the same figure stored
 * as a number, and a zip whose entry order puts the worksheet before `[Content_Types].xml`.
 */
object Fixture {
    const val NAME = "mock-money-manager.xlsx"

    /** Unit tests run with the module directory as CWD, so the repository root is a parent. */
    val file: File by lazy {
        generateSequence(File("").absoluteFile) { it.parentFile }
            .map { File(it, "data/$NAME") }
            .firstOrNull { it.isFile }
            ?: error(
                "Could not find data/$NAME by walking up from ${File("").absolutePath}. " +
                    "It is the mock export the Excel tests read.",
            )
    }
}
